const ts = 1788269400.0;
const d = new Date(ts * 1000);
console.log('Timestamp', ts, '=> UTC:', d.toISOString());
console.log();

// The timestamp actually corresponds to 1:30 PM UTC = 2026-09-01T13:30:00Z
// 6:30 PM in various timezones that are UTC-5 (e.g. CDT, EST-equivalent in summer):
// UTC-5: 1:30 PM UTC = 6:30 PM UTC-5? No, 1:30 PM - 5 = 8:30 AM
// Let's check: 6:30 PM in timezone UTC+X => 18:30 local = 13:30 UTC => offset = +5
// So timezone = UTC+5 (e.g. PKT, YEKT, MVT, TFT)

// Or: 6:30 PM EDT? EDT = UTC-4 => 18:30 EDT = 22:30 UTC. No.
// 6:30 PM IST (UTC+5:30)? => 18:30 - 5:30 = 13:00 UTC. Close but not exact.
// 6:30 PM UZT/PKT (UTC+5)? => 18:30 - 5 = 13:30 UTC. YES!

console.log('6:30 PM in UTC+5 on 2026-09-01:');
const target = new Date(Date.UTC(2026, 8, 1, 13, 30, 0));  // 18:30 local - 5h = 13:30 UTC
console.log('  UTC equivalent:', target.toISOString());
console.log('  POSIX timestamp:', target.getTime() / 1000);
console.log('  Match:', target.getTime() / 1000 === ts);
"
